const dateToken = now.toISOString().slice(0, 10).replace(/-/g, '');
return [{ json: {
  topic: 'Prepare one useful Hudson Valley real estate, homeownership, AI, tool, experiment, or story draft for editorial review',
  dateIso: now.toISOString(),
  dateToken,
  sourceBlog: 'sylvestri.com',
  sourceChannel: 'n8n-daily-editorial-draft',
  author: 'Ryan Sylvestri',
  imagePublicId: 'Gemini_Generated_Image_9tsnza9tsnza9tsn_jsi8re'
} }];

