const brief = $items('Prepare Draft Brief', 0, 0)[0].json;
const raw = $input.first().json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Missing draft payload.');
let draft;
try { draft = JSON.parse(raw); } catch { throw new Error('Draft payload was not valid JSON.'); }
const title = String(draft.title || '').trim();
const excerpt = String(draft.excerpt || '').trim();
const content = String(draft.content || '').trim();
const contentKind = String(draft.contentKind || 'story').trim();
if (!title || !excerpt || content.length < 600) throw new Error('Draft is missing required content.');
if (!['news','guide','tutorial','experiment','idea','story'].includes(contentKind)) throw new Error('Invalid contentKind.');
const slugBase = String(draft.slug || title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const slug = `${slugBase}-${brief.dateToken}`;
const tags = Array.isArray(draft.tags) && draft.tags.length >= 2 ? draft.tags.map(String) : ['editorial-draft', contentKind];
const sources = Array.isArray(draft.sources) ? draft.sources.filter((item) => item && item.title && item.url).map((item) => ({ title: String(item.title), url: String(item.url), primary: item.primary === true })) : [];
const image = `https://res.cloudinary.com/dtmh3eypz/image/upload/c_fill,g_auto,w_1600,h_900/f_auto/q_auto/${brief.imagePublicId}`;
const frontmatter = {
  title, slug, section: 'articles', contentKind,
  category: String(draft.category || 'editorial-draft'), tags,
  description: excerpt, summary: excerpt, access: 'public',
  status: 'draft', reviewState: 'draft',
  publishedAt: brief.dateIso, updatedAt: brief.dateIso,
  author: brief.author,
  featuredImage: { src: image, alt: `Editorial image for ${title}` },
  sources,
  ...(contentKind === 'news' ? { whyItMatters: String(draft.whyItMatters || 'Editorial review must establish why this reported change matters.') } : {}),
  sourceChannel: brief.sourceChannel, sourceBlog: brief.sourceBlog, slugBase,
  assetIds: [brief.imagePublicId], assetRefs: [`image:${brief.imagePublicId}`]
};
const quote = (value) => JSON.stringify(value);
const yaml = [
  `title: ${quote(frontmatter.title)}`, `slug: ${quote(frontmatter.slug)}`, `section: ${quote(frontmatter.section)}`,
  `contentKind: ${quote(frontmatter.contentKind)}`, `category: ${quote(frontmatter.category)}`, `tags: ${JSON.stringify(frontmatter.tags)}`,
  `description: ${quote(frontmatter.description)}`, `summary: ${quote(frontmatter.summary)}`, `access: ${quote(frontmatter.access)}`,
  `status: ${quote(frontmatter.status)}`, `reviewState: ${quote(frontmatter.reviewState)}`,
  `publishedAt: ${quote(frontmatter.publishedAt)}`, `updatedAt: ${quote(frontmatter.updatedAt)}`, `author: ${quote(frontmatter.author)}`,
  `featuredImage: ${JSON.stringify(frontmatter.featuredImage)}`, `sources: ${JSON.stringify(frontmatter.sources)}`,
  ...(frontmatter.whyItMatters ? [`whyItMatters: ${quote(frontmatter.whyItMatters)}`] : []),
  `sourceChannel: ${quote(frontmatter.sourceChannel)}`, `sourceBlog: ${quote(frontmatter.sourceBlog)}`, `slugBase: ${quote(frontmatter.slugBase)}`,
  `assetIds: ${JSON.stringify(frontmatter.assetIds)}`, `assetRefs: ${JSON.stringify(frontmatter.assetRefs)}`
].join('\n');
const publishBody = { section: 'articles', sourceBlog: brief.sourceBlog, sourceChannel: brief.sourceChannel, dryRun: true, requestId: `${brief.sourceBlog}-${slug}`, idempotencyKey: `${brief.sourceBlog}-${slug}`, frontmatter, content };
return [{ json: { publishBody, mdx: `---\n${yaml}\n---\n\n${content}\n`, filePath: `content/articles/${slug}.mdx`, slug } }];
